class _Var:
    """One v1 tk variable, over the job's settings store.

    Built by _make_var as a subclass of the tkinter class v1 declared that
    variable as (VAR_TYPES), because v1 code branches on it:
    SidecarConfigManager.sync_to_gui converts by isinstance(var, tk.DoubleVar)
    and friends. No Tk root is created -- tkinter's __init__ is never run.
    """

    def __init__(self, store, key):
        self._store = store
        self._key = key

    def __del__(self):
        pass

    def get(self):
        return self._store.get(self._key)

    def set(self, value):
        self._store.set(self._key, value)
        self._store.fire(self._key)

    def trace_add(self, _mode, callback):
        """A real trace: v1 reacts to writes (Border mode, convergence...)."""
        self._store.traces.setdefault(self._key, []).append(callback)
        return str(id(callback))

    def trace_remove(self, *_a, **_k):
        pass

    def __str__(self):
        return self._key + "_var"


_TK_CLASSES = {"StringVar": _tkinter.StringVar, "DoubleVar": _tkinter.DoubleVar,
               "IntVar": _tkinter.IntVar, "BooleanVar": _tkinter.BooleanVar}
_VAR_CLASSES = {name: type("_" + name, (_Var, cls), {}) for name, cls in _TK_CLASSES.items()}


def _make_var(store, key):
    """A _Var of the class v1 declared `key`_var as (StringVar if unknown)."""
    cls = _VAR_CLASSES.get(VAR_TYPES.get(key + "_var", "StringVar"), _VAR_CLASSES["StringVar"])
    return cls(store, key)


