    # ---- faster preview (fast_decode.py) ----------------------------------

    def _fast_reader(self, key, path, reader):
        """Every reader goes through the frame cache; a strict-ffmpeg source
        also gets a persistent stream in place of an ffmpeg per frame."""
        if FFmpegRGBSingleFrameReader is not None and isinstance(reader, FFmpegRGBSingleFrameReader):
            orig = reader
            total = len(orig)

            def factory(strict, orig=orig, path=path, total=total):
                s = fast_decode.rgb_stream(path, orig.width, orig.height, orig.in_range, orig.in_matrix,
                                           strict=strict, total=total)
                self._fast_streams.append(s)
                return s
            reader = fast_decode.StreamRGBReader(orig, factory)
        return fast_decode.CachedReader(reader, f"{key}|{path}", self.frame_cache)

    def _fast_depth_bytes(self, frame_idx, fps, w, h, expected_bytes):
        path = self._depth_path
        key = ("depth16", path, int(frame_idx))
        cached = self.frame_cache.get(key)
        if cached is not None:
            return cached.tobytes()
        stream_key = (path, int(w), int(h), float(fps or 0))
        if self._depth_stream is None or self._depth_stream_key != stream_key:
            if self._depth_stream is not None:
                self._depth_stream.close()
            self._depth_stream_key = stream_key
            self._depth_stream_vf = "extractplanes=y,format=gray16le"
            self._depth_stream = fast_decode.depth_stream(path, w, h, fps, self._depth_stream_vf)
        buf = self._depth_stream.read(int(frame_idx))
        if buf is None and self._depth_stream_vf != "format=gray16le":
            # v1's fallback filter, for true gray sources -- tried on a stream of its own,
            # and kept only when it reads where the planes filter didn't. A frame
            # neither has (past the map's end, a timeout) left the clip on the gray
            # filter for good, and later frames decoded differently (bug sweep A6).
            alt = fast_decode.depth_stream(path, w, h, fps, "format=gray16le")
            buf = alt.read(int(frame_idx))
            if buf is not None:
                self._depth_stream.close()
                self._depth_stream, self._depth_stream_vf = alt, "format=gray16le"
            else:
                alt.close()
        if buf is not None and len(buf) == expected_bytes:
            self.frame_cache.put(key, np.frombuffer(buf, dtype=np.uint8))
            return buf
        return None

    def _close_fast(self):
        for s in self._fast_streams:
            s.close()
        self._fast_streams = []
        if self._depth_stream is not None:
            self._depth_stream.close()
        self._depth_stream = None
        self._depth_stream_key = None
        self.frame_cache.clear()

    # ---- the widget methods, as the controller needs them ----------------

    def _set_load_button(self, text, loading):
        self.hooks.loading(bool(loading))

    def _update_nav_controls(self):
        self.hooks.nav(self.current_video_index, len(self.video_list))

    def _request_window_resize(self):
        pass

