    def __init__(self, keys, hooks):
        self.hooks = hooks
        self.store = _Store()
        for key in keys:
            setattr(self, key + "_var", _make_var(self.store, key))
        for var_name, key in self.VAR_KEYS.items():
            cls = _VAR_CLASSES.get(VAR_TYPES.get(var_name + "_var", "StringVar"), _VAR_CLASSES["StringVar"])
            setattr(self, var_name + "_var", cls(self.store, key))
        self.info = _Store()
        for key in self.INFO_KEYS:
            setattr(self, key + "_var", _Var(self.info, key))
        messagebox._hooks = hooks
        # v1 names the window after the clip only when it has no shell; the
        # window is Studio's here.
        self.shell = True
        self.sidecar_manager = SidecarConfigManager()
        self.preview_original_left_tensor = None
        self.preview_blended_right_tensor = None
        # v1's batch flag, which Move to Finish checks. The batch is the other
        # engine's here; the page keeps Move to Finish off while it runs.
        self.is_processing = False
        self.previewer = PreviewerCore(self, hooks)

