    # -- v1 MergingGUI._find_preview_sources_callback (merging_gui.py:4643)
    def _find_preview_sources_callback(self) -> list:
        """
        A callback function for the VideoPreviewer.
        It scans the folders and returns a list of dictionaries,
        where each dictionary contains the paths to the source files for one video.
        """
        inpainted_folder = self.inpainted_folder_var.get()
        if os.path.isfile(inpainted_folder):
            # A single FILE may be selected here (redo-one-scene workflow):
            # preview just that clip instead of rejecting the path.
            all_videos = [inpainted_folder]
        elif os.path.isdir(inpainted_folder):
            all_videos = sorted(
                glob.glob(os.path.join(glob.escape(inpainted_folder), "*.mp4"))
                + glob.glob(os.path.join(glob.escape(inpainted_folder), "*.mov"))
                + glob.glob(os.path.join(glob.escape(inpainted_folder), "*.mkv"))
            )
        else:
            messagebox.showerror("Error", "Inpainted Video Folder is not a valid directory or file.")
            return []

        # NOTE: must admit _inpainted_dual_sbs too — the old pattern silently
        # filtered every dual-eye clip out before the loop even ran, which is why
        # they never appeared in the previewer at all.
        inpaint_pattern = re.compile(r"_inpainted_(right_eye|(dual_)?sbs)F?\.(mp4|mov|mkv)$")
        valid_inpainted_videos = [f for f in all_videos if inpaint_pattern.search(f)]

        video_source_list = []
        self._clear_border_info()  # Clear border info before scanning

        for inpainted_path in valid_inpainted_videos:
            base_name = os.path.basename(inpainted_path)
            inpaint_suffix_reg = r"_inpainted_right_eyeF?\.(mp4|mov|mkv)$"
            sbs_suffix_reg = r"_inpainted_(dual_)?sbsF?\.(mp4|mov|mkv)$"

            is_sbs_input = bool(re.search(sbs_suffix_reg, base_name))
            is_dual_eye_sbs = bool(re.search(r"_inpainted_dual_sbsF?\.(mp4|mov|mkv)$", base_name))
            match = re.search(sbs_suffix_reg if is_sbs_input else inpaint_suffix_reg, base_name)
            if not match:
                continue
            suffix_to_remove = match.group(0)
            core_name_with_width = base_name[: -len(suffix_to_remove)]

            last_underscore_idx = core_name_with_width.rfind("_")
            if last_underscore_idx == -1:
                logger.warning(
                    f"Preview Scan: Skipping '{base_name}'. Could not determine core name (expected format '..._width_suffix.mp4')."
                )
                continue
            core_name = core_name_with_width[:last_underscore_idx]

            # --- NEW: Read sidecar file for this clip ---
            clip_sidecar_data = self._read_clip_sidecar(inpainted_path, core_name)
            logger.debug(
                f"Preview Scan: Sidecar for '{core_name}': convergence_plane={clip_sidecar_data.get('convergence_plane')}, max_disparity={clip_sidecar_data.get('max_disparity')}, left_border={clip_sidecar_data.get('left_border')}, right_border={clip_sidecar_data.get('right_border')}"
            )
            left_border = clip_sidecar_data.get("left_border", 0.0)
            right_border = clip_sidecar_data.get("right_border", 0.0)
            self._update_border_info(left_border, right_border)
            # --- END NEW ---

            mask_folder = self.mask_folder_var.get()
            # A single FILE may be selected here; if it belongs to this clip use
            # it directly (honors an explicit hi-res splat choice), otherwise
            # scan its containing folder.
            _explicit_splat = None
            if mask_folder and os.path.isfile(mask_folder):
                if core_name in os.path.basename(mask_folder):
                    _explicit_splat = mask_folder
                mask_folder = os.path.dirname(mask_folder)
            splatted4_pattern = os.path.join(glob.escape(mask_folder), f"{glob.escape(core_name)}_*_splatted4*.mp4")
            splatted2_pattern = os.path.join(glob.escape(mask_folder), f"{glob.escape(core_name)}_*_splatted2*.mp4")
            logger.debug(
                f"  - Searching for splatted file with patterns: '{splatted4_pattern}' and '{splatted2_pattern}'"
            )
            # Include DNxHR combined grids (.mov), which share the same [mask|splat]
            # / quad layout and so composite identically to the 8-bit .mp4 grids.
            splatted4_matches = glob.glob(splatted4_pattern) + glob.glob(
                os.path.join(glob.escape(mask_folder), f"{glob.escape(core_name)}_*_splatted4*.mov")
            )
            splatted2_matches = glob.glob(splatted2_pattern) + glob.glob(
                os.path.join(glob.escape(mask_folder), f"{glob.escape(core_name)}_*_splatted2*.mov")
            )
            # Explicitly selected splat file wins over glob discovery.
            if _explicit_splat:
                _ebn = os.path.basename(_explicit_splat).lower()
                if "_splatted4" in _ebn:
                    splatted4_matches = [_explicit_splat]
                elif "_splatted2" in _ebn:
                    splatted2_matches = [_explicit_splat]

            # Legacy DNxHR *separate-file* split pairs ({prefix}_splat.mov +
            # {prefix}_mask.mp4) still can't be previewed (two files, not a grid).
            # The newer combined _splatted2.mov grid is handled by the globs above.
            _split_matches = glob.glob(os.path.join(glob.escape(mask_folder), f"{glob.escape(core_name)}_*_splat.mov")) or glob.glob(
                os.path.join(glob.escape(mask_folder), "splat", f"{glob.escape(core_name)}_*_splat.mov")
            )
            if _split_matches and not (splatted4_matches or splatted2_matches):
                logger.info(
                    f"Preview Scan: '{base_name}' uses legacy DNxHR separate split files "
                    "(splat.mov + mask.mp4). Preview supports the combined _splatted2.mov grid instead; "
                    "the batch render still handles the separate pair correctly."
                )
                continue

            source_dict = {
                "source_video": inpainted_path,  # Primary key for VideoPreviewer
                "inpainted": inpainted_path,
                "splatted": None,
                "original": None,
                "is_sbs_input": is_sbs_input,
                "is_dual_eye_sbs": is_dual_eye_sbs,
                "is_quad_input": False,
                "sidecar": clip_sidecar_data,  # Store sidecar data for borders
                "core_name": core_name,  # v2: the put-back (core.removal.putback)
            }

            if is_dual_eye_sbs:
                # Pair with the _splatted2D grid that produced this inpaint. The grid
                # is row-matched (top = left eye, bottom = right), so the preview can
                # composite it exactly the way the render now does.
                _d = [c for c in (splatted2_matches or []) if "_splatted2d" in os.path.basename(c).lower()]
                if not _d:
                    logger.info(
                        f"Preview Scan: Skipping dual-eye '{base_name}' — no _splatted2D grid found "
                        f"in '{mask_folder}'. Preview needs it to composite; the render will fall "
                        f"back to raw passthrough."
                    )
                    continue
                source_dict["splatted"] = _d[0]
                # v2 (bug sweep 2026-10-09 #19): the mask side is found when the clip is
                # first shown (mask_side.mask_side_of), not by opening every grid here
                # The untouched source video is the grain-matching reference. It is
                # NOT used for compositing on this path (both eyes come from the
                # grid) — but without it the grain popup's master pane silently
                # falls back to the other inpainted eye, which is itself VAE-
                # softened and would set the sigma target far too low.
                _orig_field = self.original_folder_var.get()
                source_dict["original"] = (
                    _orig_field
                    if _orig_field and os.path.isfile(_orig_field)
                    else self._find_video_by_core_name(_orig_field, core_name)
                )
                if not source_dict["original"]:
                    logger.info(
                        f"Preview Scan: dual-eye '{base_name}' has no source video for '{core_name}' "
                        f"in '{_orig_field}'. Compositing is unaffected, but the grain popup's "
                        f"master reference will fall back to the other eye."
                    )
                logger.debug(f"  - Found dual-eye grid: {os.path.basename(_d[0])}")
                video_source_list.append(source_dict)
                continue

            if splatted4_matches:
                splatted_path = splatted4_matches[0]
                logger.debug(f"  - Found quad-splatted match: {os.path.basename(splatted_path)}")
                source_dict["splatted"] = splatted_path
                source_dict["is_quad_input"] = True  # Set flag for quad-splatted input
                # 'original' remains None, which is the necessary structural fix for the crash
            elif splatted2_matches:
                splatted_path = splatted2_matches[0]
                logger.debug(f"  - Found dual-splatted match: {os.path.basename(splatted_path)}")
                source_dict["splatted"] = splatted_path
                # A single FILE may be selected in the Original field too — use it
                # directly instead of globbing its folder by core name.
                _orig_field = self.original_folder_var.get()
                original_path = (
                    _orig_field
                    if os.path.isfile(_orig_field)
                    else self._find_video_by_core_name(_orig_field, core_name)
                )

                if original_path:
                    logger.debug(f"  - Found matching original video: {os.path.basename(original_path)}")
                    source_dict["original"] = original_path
                else:
                    logger.warning(
                        f"  - For dual-splatted input '{base_name}', the original video '{core_name}.*' was not found. It will be treated as optional."
                    )
            else:
                logger.warning(
                    f"Preview Scan: Skipping '{base_name}'. No matching splatted file found in '{mask_folder}'."
                )
                continue  # Skip to the next video if no splatted file is found

            video_source_list.append(source_dict)
        return video_source_list

    # -- v1 MergingGUI._apply_preview_brightness (merging_gui.py:4834)
    def _apply_preview_brightness(self, rgb_np, params):
        """View-only exposure lift for the merge preview: multiplies the
        finished display frame so dark scenes read better on screen. No-op at
        1.0 (default), so previews are byte-identical until touched. Operates
        only on the array handed back to the previewer -- never on the blend,
        grain, grade, or anything encoded to the export."""
        try:
            b = float(params.get("preview_brightness", 1.0))
        except Exception:
            b = 1.0
        if abs(b - 1.0) < 1e-6:
            return rgb_np
        return np.clip(rgb_np.astype(np.float32) * b, 0, 255).astype(np.uint8)

    # -- v1 MergingGUI._preview_processing_callback (merging_gui.py:4848)
    def _preview_processing_callback(self, source_frames: dict, params: dict) -> Optional[Image.Image]:
        """
        This function contains the actual blending logic for the preview.
        It's called by the VideoPreviewer module.
        """
        try:
            # --- FIX: Always get the latest parameters when the preview is updated ---
            # This ensures that changing the preview source uses the current slider values.
            params = self.get_current_settings()
            if not params:
                return None  # Exit if settings are invalid
            # --- END FIX ---

            # 1. Extract raw tensors from the source_frames dict
            inpainted_tensor_full = source_frames.get("inpainted")
            splatted_tensor_raw = source_frames.get("splatted")
            original_tensor = source_frames.get("original")  # Will be None for quad input

            if inpainted_tensor_full is None or splatted_tensor_raw is None:
                raise ValueError("Missing 'inpainted' or 'splatted' source for preview.")

            # 2. Determine input type and metadata
            current_source_metadata = self.previewer.video_list[self.previewer.current_video_index]
            is_sbs_input = current_source_metadata.get("is_sbs_input", False)
            is_quad_input = current_source_metadata.get("is_quad_input", False)
            is_dual_eye_sbs = current_source_metadata.get("is_dual_eye_sbs", False)
            from .mask_side import mask_side_of  # v2: found once, when first shown (#19)
            dual_mask_side = mask_side_of(current_source_metadata)

            # Get flip flag from sidecar or filename
            sidecar_data = current_source_metadata.get("sidecar", {})
            flip_horizontal = sidecar_data.get("flip_horizontal", False)
            if not flip_horizontal:
                # Check for "F" suffix in inpainted filename as fallback
                inpainted_path = current_source_metadata.get("inpainted", "")
                if inpainted_path and os.path.splitext(os.path.basename(inpainted_path))[0].endswith("F"):
                    flip_horizontal = True

            # Define the processing device based on the 'use_gpu' parameter
            use_gpu = params.get("use_gpu", False) and torch.cuda.is_available()
            device = "cuda" if use_gpu else "cpu"

            # 3. Extract frame parts and move to device
            # Extract Inpainted Right Eye
            inpainted = (
                inpainted_tensor_full[:, :, :, inpainted_tensor_full.shape[3] // 2 :]
                if is_sbs_input
                else inpainted_tensor_full
            ).to(device)

            splatted_tensor = splatted_tensor_raw.to(device)
            _, _, H, W = splatted_tensor.shape

            if is_dual_eye_sbs:
                # _splatted2D grid: [Lmask|Lwarp] over [Rmask|Rwarp]. The right eye
                # drives the standard preview slots; the left eye is composited
                # separately so SBS/anaglyph views show a correct stereo pair.
                half_h, half_w = H // 2, W // 2
                m_cols = slice(0, half_w) if dual_mask_side == "left" else slice(half_w, None)
                w_cols = slice(half_w, None) if dual_mask_side == "left" else slice(0, half_w)
                mask_raw = splatted_tensor[:, :, half_h:, m_cols]
                right_eye_original = splatted_tensor[:, :, half_h:, w_cols]
                _l_warp = splatted_tensor[:, :, :half_h, w_cols]
                _l_mask = splatted_tensor[:, :, :half_h, m_cols].mean(dim=1, keepdim=True)
                _fw = inpainted_tensor_full.shape[3]
                _l_inp = inpainted_tensor_full[:, :, :, : _fw // 2].to(device)
                _lh, _lw = _l_warp.shape[2], _l_warp.shape[3]
                if _l_inp.shape[2] != _lh or _l_inp.shape[3] != _lw:
                    _l_inp = F.interpolate(_l_inp, size=(_lh, _lw), mode="bicubic", align_corners=False).clamp(0, 1)
                if _l_mask.shape[2] != _lh or _l_mask.shape[3] != _lw:
                    _l_mask = F.interpolate(_l_mask, size=(_lh, _lw), mode="bilinear", align_corners=False)
                _l_pm = process_blend_mask(_l_mask, params, use_gpu)
                original_left = _l_warp * (1 - _l_pm) + _l_inp * _l_pm
                depth_map_vis = None
                is_dual_input = False
            elif is_quad_input:
                half_h, half_w = H // 2, W // 2
                original_left = splatted_tensor[:, :, :half_h, :half_w]
                depth_map_vis = splatted_tensor[:, :, :half_h, half_w:]
                mask_raw = splatted_tensor[:, :, half_h:, :half_w]
                right_eye_original = splatted_tensor[:, :, half_h:, half_w:]
                is_dual_input = False
            else:
                half_w = W // 2
                mask_raw = splatted_tensor[:, :, :, :half_w]
                right_eye_original = splatted_tensor[:, :, :, half_w:]
                original_left = original_tensor.to(device) if original_tensor is not None else None
                depth_map_vis = None
                is_dual_input = True

            if flip_horizontal and is_dual_input:
                # In Dual mode, original_left is the raw video (not flipped).
                # We flip it to align with the flipped inpainted/splatted tensors.
                original_left = torch.flip(original_left, dims=[3])
            # (In Quad mode, original_left is sliced from the splatted tensor and is already flipped)

            # Configure preview source dropdown based on input type
            preview_options = [
                "Blended Image",
                "Original (Left Eye)",
                "Warped (Right BG)",
                "Inpainted Right Eye",
                "Processed Mask",
                "Anaglyph 3D",
                "Dubois Anaglyph",
                "Optimized Anaglyph",
                "Side-by-Side",
                "Wigglegram",
                "Glasses-Free 3D",
            ]
            preview_options.extend(["Depth Map", "Mesh Warp"])
            self.previewer.set_preview_source_options(preview_options)

            # Convert mask to grayscale ON DEVICE
            mask = torch.mean(mask_raw, dim=1, keepdim=True)

            hires_H, hires_W = right_eye_original.shape[2], right_eye_original.shape[3]

            # --- Optimized Resizing ---
            if inpainted.shape[2] != hires_H or inpainted.shape[3] != hires_W:
                target_aspect = hires_W / hires_H
                inpaint_aspect = inpainted.shape[3] / inpainted.shape[2]

                if abs(inpaint_aspect - target_aspect) > 0.01:
                    if inpaint_aspect > target_aspect:
                        new_w = hires_W
                        new_h = int(round(hires_W / inpaint_aspect))
                    else:
                        new_h = hires_H
                        new_w = int(round(hires_H * inpaint_aspect))
                    inpainted = F.interpolate(inpainted, size=(new_h, new_w), mode="bicubic", align_corners=False)
                    mask = F.interpolate(mask, size=(new_h, new_w), mode="bilinear", align_corners=False)

                # Final resize to target dimensions
                inpainted = F.interpolate(inpainted, size=(hires_H, hires_W), mode="bicubic", align_corners=False)
                mask = F.interpolate(mask, size=(hires_H, hires_W), mode="bilinear", align_corners=False)

            # ... (Mask processing) ...
            processed_mask = mask.clone()
            if params.get("mask_binarize_threshold", -1.0) >= 0.0:
                processed_mask = (processed_mask > params["mask_binarize_threshold"]).float()

            if params.get("mask_dilate_kernel_size", 0) > 0:
                processed_mask = apply_mask_dilation(processed_mask, int(params["mask_dilate_kernel_size"]), use_gpu)

            if params.get("mask_blur_kernel_size", 0) > 0:
                processed_mask = apply_gaussian_blur(processed_mask, int(params["mask_blur_kernel_size"]), use_gpu)

            if params.get("shadow_shift", 0) > 0:
                processed_mask = apply_shadow_blur(
                    processed_mask,
                    int(params["shadow_shift"]),
                    params["shadow_start_opacity"],
                    params["shadow_opacity_decay"],
                    params["shadow_min_opacity"],
                    params["shadow_decay_gamma"],
                    use_gpu,
                )

            # Color Transfer
            if params.get("enable_color_transfer", False):
                if original_left is not None:
                    # Color transfer returns 3D, we must unsqueeze to keep it 4D
                    inpainted = apply_color_transfer(original_left, inpainted).unsqueeze(0).to(device)  # v2: bug sweep A8

            blended_frame = right_eye_original * (1 - processed_mask) + inpainted * processed_mask

            # v2 (user, 2026-10-06): the erased object put back (core.removal.putback)
            from core.removal import putback as _putback
            _pb = _putback.find(self.original_folder_var.get(), current_source_metadata.get("core_name", ""))
            if _pb is not None:
                original_left, blended_frame = _pb.apply(
                    original_left, blended_frame, int(self.previewer.frame_scrubber_var.get()), flip_horizontal)

            # Borders
            left_border = sidecar_data.get("left_border", 0.0)
            right_border = sidecar_data.get("right_border", 0.0)

            if self.add_borders_var.get() and (left_border > 0 or right_border > 0):
                if original_left is not None:
                    original_left, blended_frame = apply_borders_to_frames(
                        left_border, right_border, original_left, blended_frame
                    )
                else:
                    _, blended_frame = apply_borders_to_frames(left_border, right_border, blended_frame, blended_frame)

            # ... (Preview selection logic) ...
            preview_source = self.preview_source_var.get()
            final_frame_4d = None

            if preview_source == "Blended Image":
                final_frame_4d = blended_frame
            elif preview_source == "Inpainted Right Eye":
                final_frame_4d = inpainted
            elif preview_source == "Original (Left Eye)":
                final_frame_4d = original_left if original_left is not None else torch.zeros_like(blended_frame)
            elif preview_source == "Warped (Right BG)":
                final_frame_4d = right_eye_original
            elif preview_source == "Processed Mask":
                final_frame_4d = processed_mask.repeat(1, 3, 1, 1)

            # Mask highlighter: overlay the feathered mask (tint) + cutout
            # outline on image-bearing sources so slider changes are visible
            # directly on the picture.
            if (
                final_frame_4d is not None
                and getattr(self, "mask_highlight_var", None) is not None
                and self.mask_highlight_var.get()
                and preview_source in ("Blended Image", "Warped (Right BG)", "Inpainted Right Eye")
            ):
                final_frame_4d = apply_mask_highlight(final_frame_4d, processed_mask)

            if preview_source == "Anaglyph 3D":
                if original_left is not None:
                    # Red channel from grayscale left, Green/Blue from right
                    left_gray = (
                        original_left[:, 0:1, :, :] * 0.299
                        + original_left[:, 1:2, :, :] * 0.587
                        + original_left[:, 2:3, :, :] * 0.114
                    )
                    final_frame_4d = torch.cat(
                        [left_gray, blended_frame[:, 1:2, :, :], blended_frame[:, 2:3, :, :]], dim=1
                    )
                else:
                    final_frame_4d = blended_frame
            elif preview_source == "Dubois Anaglyph":
                if original_left is not None:
                    final_frame_4d = apply_dubois_anaglyph_torch(original_left, blended_frame)
                else:
                    final_frame_4d = blended_frame
            elif preview_source == "Optimized Anaglyph":
                if original_left is not None:
                    final_frame_4d = apply_optimized_anaglyph_torch(original_left, blended_frame)
                else:
                    final_frame_4d = blended_frame
            elif preview_source in ("Side-by-Side", "Glasses-Free 3D"):
                if original_left is not None:
                    left_np = (original_left[0].permute(1, 2, 0) * 255.0).clamp(0, 255).to(torch.uint8).cpu().numpy()
                    _right_view = blended_frame
                    if (preview_source == "Glasses-Free 3D" and getattr(self, "mask_highlight_var", None) is not None
                            and self.mask_highlight_var.get()):
                        _right_view = apply_mask_highlight(blended_frame, processed_mask)  # v2: as on Blended Image
                    right_np = (_right_view[0].permute(1, 2, 0) * 255.0).clamp(0, 255).to(torch.uint8).cpu().numpy()
                    if (preview_source != "Glasses-Free 3D" and getattr(self.previewer, "sbs_cross_eye_var", None)
                            and self.previewer.sbs_cross_eye_var.get()):
                        sbs_np = np.concatenate([right_np, left_np], axis=1)
                    else:
                        sbs_np = np.concatenate([left_np, right_np], axis=1)
                    if flip_horizontal:  # v2: as the batch flips its SBS
                        sbs_np = np.ascontiguousarray(sbs_np[:, ::-1])
                    sbs_np = self._apply_preview_brightness(sbs_np, params)
                    sbs_img = Image.fromarray(sbs_np)
                    if preview_source == "Glasses-Free 3D":
                        sbs_img.info["sr3d"] = True   # v2: the glue splits it (studio/sr_display.py)
                        sbs_img.info["sr3d_np"] = sbs_np   # ...from this, not by reading the image back
                    return sbs_img
                else:
                    final_frame_4d = blended_frame
            elif preview_source == "Wigglegram":
                if original_left is not None:
                    if flip_horizontal:  # v2: the eyes flipped back (they swap)
                        self.previewer._start_wigglegram_animation(
                            torch.flip(blended_frame, dims=[3]), torch.flip(original_left, dims=[3]))
                    else:
                        self.previewer._start_wigglegram_animation(original_left, blended_frame)
                return None
            elif preview_source == "Depth Map" and depth_map_vis is not None:
                final_frame_4d = depth_map_vis
            elif preview_source == "Mesh Warp" and depth_map_vis is not None:
                from core.common.mesh_warp import run_fusion_stereo

                left_np = (original_left.squeeze(0).permute(1, 2, 0).cpu().numpy() * 255).astype(np.uint8)
                left_bgr = cv2.cvtColor(left_np, cv2.COLOR_RGB2BGR)
                depth_np = depth_map_vis.squeeze(0).mean(dim=0).cpu().numpy()

                l_img, r_img = run_fusion_stereo(
                    image=left_bgr,
                    depth=depth_np,
                    disparity=float(sidecar_data.get("max_disparity", 25.0)),
                    convergence=1.0 - float(sidecar_data.get("convergence_plane", 0.5)),
                    view_bias=float(self.APP_DEFAULTS.get("MESH_WARP_VIEW_BIAS", -1.0)),
                    dolly_zoom=float(self.APP_DEFAULTS.get("MESH_WARP_DOLLY_ZOOM", 0.0)),
                    extrusion_scale=float(self.APP_DEFAULTS.get("MESH_WARP_EXTRUSION_SCALE", 1.0)),
                    density_x=int(left_bgr.shape[1]),
                    density_y=int(left_bgr.shape[0]),
                )

                if getattr(self.previewer, "sbs_cross_eye_var", None) and self.previewer.sbs_cross_eye_var.get():
                    sbs_np = np.concatenate([r_img, l_img], axis=1)
                else:
                    sbs_np = np.concatenate([l_img, r_img], axis=1)

                if flip_horizontal:  # v2: as the batch flips its SBS
                    sbs_np = np.ascontiguousarray(sbs_np[:, ::-1])
                sbs_rgb = cv2.cvtColor(sbs_np, cv2.COLOR_BGR2RGB)
                return Image.fromarray(sbs_rgb)
            # (else: the first chain's pick stands -- v2: it was set to the blend
            # here, which hid those views and Highlight Mask)

            if final_frame_4d is None:
                final_frame_4d = blended_frame

            if flip_horizontal:
                final_frame_4d = torch.flip(final_frame_4d, dims=[3])

            # Store for saving SBS (CPU side)
            if not getattr(self, "_capture_sbs_eyes", False):  # v2: only Save SBS's render
                pass
            elif flip_horizontal:
                # When unflipping an SBS [L, R], the result is [flip(R), flip(L)]
                self.preview_original_left_tensor = torch.flip(blended_frame, dims=[3]).squeeze(0).cpu()
                if original_left is not None:
                    self.preview_blended_right_tensor = torch.flip(original_left, dims=[3]).squeeze(0).cpu()
                else:
                    self.preview_blended_right_tensor = torch.zeros_like(blended_frame).squeeze(0).cpu()
            else:
                if original_left is not None:
                    self.preview_original_left_tensor = original_left.squeeze(0).cpu()
                else:
                    self.preview_original_left_tensor = torch.zeros_like(blended_frame).squeeze(0).cpu()
                self.preview_blended_right_tensor = blended_frame.squeeze(0).cpu()

            # 5. Convert to PIL Image
            final_uint8 = (final_frame_4d[0].permute(1, 2, 0) * 255.0).clamp(0, 255).to(torch.uint8)
            final_np = final_uint8.cpu().numpy()
            # View-only brightness, but not on the depth/mask diagnostics --
            # scaling those would misrepresent the values they exist to show.
            if preview_source not in ("Depth Map", "Mask", "Processed Mask"):
                final_np = self._apply_preview_brightness(final_np, params)
            return Image.fromarray(final_np)

        except Exception as e:
            logger.error(f"Error in preview processing callback: {e}", exc_info=True)
            return None

    # -- v1 MergingGUI._grain_mask_coverage (merging_gui.py:5160)
    def _grain_mask_coverage(self, f_np, ctx) -> float:
        """Fill coverage of one splat frame's mask panel, 0-1.

        Takes ctx rather than reading Tk vars so it is safe to call from the
        suggestion-scan thread: a Tcl call off the main thread takes the
        interpreter down with no Python traceback.
        """
        h, w = f_np.shape[0], f_np.shape[1]
        eye = str(ctx.get("eye", "R")).upper()
        if ctx.get("is_dual_eye_sbs"):
            _rows = slice(h // 2, None) if eye == "R" else slice(0, h // 2)
            _cols = slice(w // 2, None) if ctx.get("mask_side") == "right" else slice(0, w // 2)
            panel = f_np[_rows, _cols]
        elif ctx.get("is_quad_input"):
            panel = f_np[h // 2:, : w // 2]
        else:
            panel = f_np[:, : w // 2]
        return float(panel.mean()) / 255.0

    # -- v1 MergingGUI._render_grain_frame (merging_gui.py:5179)
    def _render_grain_frame(self, ctx, frame_idx, params, grained=True):
        """Mirror of the batch blend for ONE frame; returns dict of results.

        ctx carries the clip's readers and topology flags:
        inp_reader / splat_reader / orig_reader, is_sbs_input, is_quad_input,
        is_dual_eye_sbs, mask_side, flip_horizontal, eye. Passing them in rather
        than closing over them is what lets the batch loop reuse this without
        opening a preview window.
        """
        inp_reader = ctx["inp_reader"]
        splat_reader = ctx["splat_reader"]
        orig_reader = ctx.get("orig_reader")
        is_sbs_input = bool(ctx.get("is_sbs_input"))
        is_quad_input = bool(ctx.get("is_quad_input"))
        is_dual_eye_sbs = bool(ctx.get("is_dual_eye_sbs"))
        grain_mask_side = ctx.get("mask_side", "left")
        flip_horizontal = bool(ctx.get("flip_horizontal"))

        with torch.no_grad():
            if not params:
                return None
            use_gpu = params.get("use_gpu", False) and torch.cuda.is_available()
            device = "cuda" if use_gpu else "cpu"

            inp_np = inp_reader.get_batch([frame_idx]).asnumpy()
            inpainted_full = torch.from_numpy(inp_np).permute(0, 3, 1, 2).float() / 255.0
            inpainted = (
                inpainted_full[:, :, :, inpainted_full.shape[3] // 2:] if is_sbs_input else inpainted_full
            ).to(device)

            spl_np = splat_reader.get_batch([frame_idx]).asnumpy()
            splatted = torch.from_numpy(spl_np).permute(0, 3, 1, 2).float().to(device) / 255.0
            _, _, H, W = splatted.shape
            if is_dual_eye_sbs:
                # Mirror the render: composite the inpainted eye back over its
                # own pristine warped panel through the occlusion mask, then
                # apply the fill FX. Showing the raw inpaint here instead would
                # make the popup disagree with what actually gets written.
                eye_is_right = str(ctx.get("eye", "R")).upper() == "R"
                fw = inpainted_full.shape[3]
                eye = (
                    inpainted_full[:, :, :, fw // 2:] if eye_is_right else inpainted_full[:, :, :, : fw // 2]
                ).to(device)
                rows = slice(H // 2, None) if eye_is_right else slice(0, H // 2)
                m_cols = slice(0, W // 2) if grain_mask_side == "left" else slice(W // 2, None)
                w_cols = slice(W // 2, None) if grain_mask_side == "left" else slice(0, W // 2)
                mask_raw = splatted[:, :, rows, m_cols]
                warp = splatted[:, :, rows, w_cols]
                hires_H, hires_W = warp.shape[2], warp.shape[3]
                if eye.shape[2] != hires_H or eye.shape[3] != hires_W:
                    eye = F.interpolate(
                        eye, size=(hires_H, hires_W), mode="bicubic", align_corners=False
                    ).clamp(0, 1)
                mask = mask_raw.mean(dim=1, keepdim=True)
                if mask.shape[2] != hires_H or mask.shape[3] != hires_W:
                    mask = F.interpolate(
                        mask, size=(hires_H, hires_W), mode="bilinear", align_corners=False
                    )
                pm = process_blend_mask(mask, params, use_gpu)
                blended = warp * (1 - pm) + eye * pm
                if grained:
                    gp = dict(
                        enable=True,
                        amount=params["grain_amount"],
                        size=params["grain_size"],
                        luma_falloff=params["grain_luma_falloff"],
                        chroma=params["grain_chroma"],
                        brightness=params.get("fill_brightness", 0.0),
                        contrast=params.get("fill_contrast", 1.0),
                        red_reduce=params.get("fill_red_reduce", 0.0),
                    )
                    seed = int(params["grain_seed"])
                    gen = torch.Generator(device=device)
                    gen.manual_seed(seed if seed >= 0 else 1234)
                    blended = apply_fill_fx(blended, pm, gp, generator=gen)
                # Master reference: the untouched SOURCE video. Both eyes here
                # went through the splat, which resamples and softens the
                # film's grain — measuring against the other eye would set the
                # target too low. Falls back to the other eye if no source is
                # found, which still beats no reference at all.
                master = None
                master_fallback = not (orig_reader is not None and frame_idx < len(orig_reader))
                if orig_reader is not None and frame_idx < len(orig_reader):
                    o_np = orig_reader.get_batch([frame_idx]).asnumpy()
                    master = torch.from_numpy(o_np).permute(0, 3, 1, 2).float().to(device) / 255.0
                    if flip_horizontal:
                        master = torch.flip(master, dims=[3])
                else:
                    master = (
                        inpainted_full[:, :, :, : fw // 2]
                        if eye_is_right
                        else inpainted_full[:, :, :, fw // 2:]
                    ).to(device)
                if master.shape[2] != hires_H or master.shape[3] != hires_W:
                    master = F.interpolate(
                        master, size=(hires_H, hires_W), mode="bicubic", align_corners=False
                    ).clamp(0, 1)
                return {
                    "blended": blended[0].cpu(),
                    "mask": pm[0].cpu(),
                    "original_left": master[0].cpu(),
                    "master_fallback": master_fallback,
                }
            if is_quad_input:
                original_left = splatted[:, :, : H // 2, : W // 2]
                mask_raw = splatted[:, :, H // 2:, : W // 2]
                warped = splatted[:, :, H // 2:, W // 2:]
                hires_H, hires_W = H // 2, W // 2
                master_fallback = False
            else:
                mask_raw = splatted[:, :, :, : W // 2]
                warped = splatted[:, :, :, W // 2:]
                hires_H, hires_W = H, W // 2
                master_fallback = not (orig_reader is not None and frame_idx < len(orig_reader))
                if orig_reader is not None and frame_idx < len(orig_reader):
                    o_np = orig_reader.get_batch([frame_idx]).asnumpy()
                    original_left = torch.from_numpy(o_np).permute(0, 3, 1, 2).float().to(device) / 255.0
                    if flip_horizontal:
                        original_left = torch.flip(original_left, dims=[3])
                else:
                    original_left = None

            mask = mask_raw.mean(dim=1, keepdim=True)
            inpainted, mask = self._merge_resize_inpaint(inpainted, mask, hires_H, hires_W)

            pm = mask.clone()
            if params["mask_binarize_threshold"] >= 0.0:
                pm = (mask > params["mask_binarize_threshold"]).float()
            if params["mask_dilate_kernel_size"] > 0:
                pm = apply_mask_dilation(pm, params["mask_dilate_kernel_size"], use_gpu)
            if params["mask_blur_kernel_size"] > 0:
                pm = apply_gaussian_blur(pm, params["mask_blur_kernel_size"], use_gpu)
            if params["shadow_shift"] > 0:
                pm = apply_shadow_blur(
                    pm,
                    params["shadow_shift"],
                    params["shadow_start_opacity"],
                    params["shadow_opacity_decay"],
                    params["shadow_min_opacity"],
                    params["shadow_decay_gamma"],
                    use_gpu,
                )

            blended = warped * (1 - pm) + inpainted * pm
            if grained:
                blended = apply_fill_color_correction(
                    blended, pm, params.get("fill_brightness", 0.0), params.get("fill_contrast", 1.0)
                )
            if grained and params.get("fill_red_reduce", 0) > 0:
                blended = apply_fill_red_reduction(blended, pm, params["fill_red_reduce"])
            if grained:
                # The preview ALWAYS shows grain so it can be tuned; the
                # enable checkbox only governs whether the render applies it.
                seed = int(params["grain_seed"])
                gen = torch.Generator(device=device)
                gen.manual_seed(seed if seed >= 0 else 1234)  # stable pattern while tuning
                blended = apply_film_grain_masked(
                    blended,
                    pm,
                    amount=params["grain_amount"],
                    grain_size=params["grain_size"],
                    luma_falloff=params["grain_luma_falloff"],
                    chroma_amount=params["grain_chroma"],
                    generator=gen,
                )
            return {
                "blended": blended[0].cpu(),
                "mask": pm[0].cpu(),
                "original_left": original_left[0].cpu() if original_left is not None else None,
                "master_fallback": master_fallback,
            }

    # -- v1 MergingGUI._grain_match_stats (merging_gui.py:5356)
    def _grain_match_stats(self, res_before, res_after=None, *, grain_size, luma_falloff, chroma):
        """Measure master/fill sigma, calibrate the gain, and solve the Amount.

        res_before is the UNGRAINED render; res_after (optional) is the grained
        one, used only for the popup's live 'fill' readout. Returns a dict with
        ok/reason so callers can distinguish 'no answer' from 'answer is zero' —
        the batch loop must not write a solved 0.0 into a sidecar just because
        the clip had nothing measurable in it.
        """
        out = {
            "ok": False, "reason": "", "amount": None, "gain": None,
            "master_sigma": None, "fill_sigma": None, "fill_sigma_raw": None,
            "target_added": None, "coverage": 0.0,
            "master_fallback": bool(res_before.get("master_fallback")),
        }
        if not res_before:
            out["reason"] = "no render"
            return out
        blend_raw = res_before["blended"]
        pm = res_before["mask"]
        fillsel = (pm[0] > 0.5).float()
        coverage = float(fillsel.mean().item())
        out["coverage"] = coverage
        if coverage < self.GRAIN_MIN_COVERAGE:
            out["reason"] = f"fill coverage {coverage*100:.2f}% below floor"
            return out

        blended = (res_after or res_before)["blended"]
        # Luma reference: measure the master only where it is about as bright as
        # the fill. Grain sigma is strongly luma-dependent, so an unbanded
        # reading over a frame with large dark areas returns the sigma of the
        # shadows and hands the fill a target it can't reach.
        _lm = 0.299 * blended[0] + 0.587 * blended[1] + 0.114 * blended[2]
        _selb = fillsel.squeeze() > 0.5
        luma_ref = float(_lm[_selb].median().item()) if int(_selb.sum()) > 64 else None

        master_src = res_before.get("original_left")
        if master_src is None:
            inv = (pm[0] < 0.05)
            master_sigma = (
                measure_grain_sigma(blended, grain_size=grain_size, luma_ref=luma_ref)
                if int(inv.sum()) < 100
                else measure_grain_sigma(
                    blended, region_mask=inv.float(), grain_size=grain_size, luma_ref=luma_ref
                )
            )
        else:
            # Scale parity. The master arrives at the SOURCE video's resolution
            # while the blend sits at the splat's. Grain sigma changes under
            # resampling, so measuring the two at different sizes compares two
            # different films. Resize first.
            hh, ww = blended.shape[1], blended.shape[2]
            if master_src.shape[1] != hh or master_src.shape[2] != ww:
                master_src = F.interpolate(
                    master_src.unsqueeze(0), size=(hh, ww), mode="bilinear", align_corners=False
                )[0].clamp(0, 1)
            master_sigma = measure_grain_sigma(master_src, grain_size=grain_size, luma_ref=luma_ref)

        # No luma banding on the fill: the fill IS the reference band.
        fill_sigma = measure_grain_sigma(blended, region_mask=fillsel, grain_size=grain_size)
        try:
            fill_sigma_raw = measure_grain_sigma(blend_raw, region_mask=fillsel, grain_size=grain_size)
        except Exception:
            fill_sigma_raw = 0.0

        # ---- gain probe ----------------------------------------------------
        # Apply a KNOWN Amount to the ungrained fill and measure what sigma it
        # actually produced. That one number converts between the Amount
        # parameter and the sigma readouts, and it has to be measured, not
        # assumed: luma falloff, the feathered mask and the grain field's
        # post-blur renormalisation all attenuate it, landing it near 0.5 rather
        # than the 1.0 the old solver fell back to.
        PROBE = 0.02
        gain = 0.0
        try:
            _pgen = torch.Generator(device="cpu")
            _pgen.manual_seed(20260825)  # fixed, so the gain doesn't jitter
            _probe = apply_film_grain_masked(
                blend_raw.unsqueeze(0), pm.unsqueeze(0), amount=PROBE, grain_size=grain_size,
                luma_falloff=luma_falloff, chroma_amount=chroma, generator=_pgen,
            )[0]
            _ps = measure_grain_sigma(_probe, region_mask=fillsel, grain_size=grain_size)
            _added_sq = _ps * _ps - fill_sigma_raw * fill_sigma_raw
            if _added_sq > 0:
                gain = (_added_sq ** 0.5) / PROBE
        except Exception as _e:
            logger.debug(f"grain gain probe failed: {_e}")
        if gain <= 1e-4:
            gain = 0.5  # measured typical, not the old nominal 1.0

        out.update(
            master_sigma=master_sigma, fill_sigma=fill_sigma,
            fill_sigma_raw=fill_sigma_raw, gain=gain,
        )
        target_sq = master_sigma * master_sigma - fill_sigma_raw * fill_sigma_raw
        if target_sq <= 0:
            out["target_added"] = 0.0
            out["amount"] = 0.0
            out["ok"] = True
            out["reason"] = "fill already at or above master"
            return out
        target = target_sq ** 0.5
        out["target_added"] = target
        out["amount"] = max(0.0, min(0.12, target / max(gain, 1e-4)))
        out["ok"] = True
        return out

    # -- v1 MergingGUI._write_grain_sidecar (merging_gui.py:5619)
    def _write_grain_sidecar(self, inpainted_path, core_name, orig_path, keys):
        """Merge `keys` into the clip's sidecar. Returns (path, resolved_ok).

        Writes to the FIRST location the reader checks, preferring an existing
        sidecar so we update in place rather than orphan it. resolved_ok reports
        whether the merge's own reader can actually see what we wrote — a false
        there means the clip's core name differs from its file name.
        """
        sc_path = None
        for _folder in (os.path.dirname(inpainted_path), os.path.dirname(orig_path) if orig_path else None):
            if _folder:
                _hit = find_sidecar_in_folder(_folder, core_name)
                if _hit:
                    sc_path = _hit
                    break
        if not sc_path:
            sc_path = find_sidecar_file(inpainted_path)
        if not sc_path:
            sc_path = os.path.join(os.path.dirname(inpainted_path), f"{core_name}.fssidecar")
        existing = {}
        if os.path.exists(sc_path):
            with open(sc_path, "r") as f:
                existing = json.load(f) or {}
        existing.update(keys)
        # whole or not at all (audit 2026-09-28, minor): written in place, a
        # failure mid-dump left the clip's sidecar truncated
        from core.common.atomic_json import write_json_atomic
        write_json_atomic(sc_path, existing, indent=4)
        check = self._read_clip_sidecar(inpainted_path, core_name)
        ok = all(check.get(k) == v for k, v in keys.items())
        return sc_path, ok

    # -- v1 MergingGUI._find_dual_eye_grain_source (merging_gui.py:5651)
    def _find_dual_eye_grain_source(self) -> Optional[dict]:
        """Locate a dual-eye clip + its _splatted2D mask grid for the grain popup.

        Mirrors the batch path's discovery. Returns a source dict shaped like the
        previewer's entries, or None. If several dual-eye clips qualify, the user
        picks one — silently grabbing the first would tune grain against a shot
        they aren't looking at.
        """
        inp_field = self.inpainted_folder_var.get()
        mask_field = self.mask_folder_var.get()
        if not inp_field or not mask_field:
            return None

        explicit_splat = mask_field if os.path.isfile(mask_field) else None
        mask_folder = os.path.dirname(mask_field) if explicit_splat else mask_field
        if os.path.isfile(inp_field):
            candidates = [inp_field]
        elif os.path.isdir(inp_field):
            candidates = sorted(
                glob.glob(os.path.join(glob.escape(inp_field), "*.mp4"))
                + glob.glob(os.path.join(glob.escape(inp_field), "*.mov"))
                + glob.glob(os.path.join(glob.escape(inp_field), "*.mkv"))
            )
        else:
            return None

        found = []
        for path in candidates:
            base = os.path.basename(path)
            if not re.search(r"_inpainted_dual_sbsF?\.(mp4|mov|mkv)$", base):
                continue
            core_with_width = base[: base.rfind("_inpainted_dual_sbs")]
            if "_" not in core_with_width:
                continue
            core_name = core_with_width[: core_with_width.rfind("_")]

            if explicit_splat and "_splatted2d" in os.path.basename(explicit_splat).lower():
                splat = explicit_splat
            else:
                cands = glob.glob(os.path.join(glob.escape(mask_folder), f"{glob.escape(core_name)}_*_splatted2*.mp4")) + glob.glob(
                    os.path.join(glob.escape(mask_folder), f"{glob.escape(core_name)}_*_splatted2*.mov")
                )
                cands = [c for c in cands if "_splatted2d" in os.path.basename(c).lower()]
                splat = cands[0] if cands else None
            if not splat:
                continue
            found.append((path, splat, core_name))

        if not found:
            return None
        if len(found) > 1:
            names = [os.path.basename(p) for p, _s, _c in found]
            choice = self._choose_from_list("Grain Preview — pick a dual-eye clip", names)
            if choice is None:
                return None
            path, splat, core_name = found[choice]
        else:
            path, splat, core_name = found[0]

        try:
            side = detect_mask_panel_side(VideoReader(splat, ctx=cpu(0)).get_batch([0]).asnumpy()[0])
        except Exception:
            side = "left"
        return {
            "inpainted": path,
            "splatted": splat,
            "original": self._find_video_by_core_name(self.original_folder_var.get(), core_name),
            "is_sbs_input": True,
            "is_quad_input": False,
            "is_dual_eye_sbs": True,
            "mask_side": side,
            "sidecar": self._read_clip_sidecar(path, core_name),
        }

    # -- v1 MergingGUI._save_preview_sbs_frame (merging_gui.py:6868)
    def _save_preview_sbs_frame(self):
        """Saves the current preview as a full side-by-side image."""
        if self.preview_original_left_tensor is None or self.preview_blended_right_tensor is None:
            messagebox.showwarning(
                "No Preview Data", "There is no preview data to save. Please load and preview a video first."
            )
            return

        try:
            # Convert tensors to PIL Images
            left_np = (self.preview_original_left_tensor.permute(1, 2, 0).numpy() * 255).astype(np.uint8)
            right_np = (self.preview_blended_right_tensor.permute(1, 2, 0).numpy() * 255).astype(np.uint8)

            left_pil = Image.fromarray(left_np)
            right_pil = Image.fromarray(right_np)

            # Check if dimensions match
            if left_pil.size != right_pil.size:
                messagebox.showerror(
                    "Dimension Mismatch",
                    "The left and right eye images have different dimensions. Cannot create SBS image.",
                )
                return

            # Create SBS image
            width, height = left_pil.size
            sbs_image = Image.new("RGB", (width * 2, height))
            sbs_image.paste(left_pil, (0, 0))
            sbs_image.paste(right_pil, (width, 0))

            # Suggest a default filename
            default_filename = "preview_sbs_frame.png"
            if self.previewer.current_video_index != -1:
                source_paths = self.previewer.video_list[self.previewer.current_video_index]
                base_name = os.path.splitext(os.path.basename(next(iter(source_paths.values()))))[0]
                frame_num = int(self.previewer.frame_scrubber_var.get())
                default_filename = f"{base_name}_frame_{frame_num:05d}_SBS.png"

            filepath = filedialog.asksaveasfilename(
                title="Save SBS Preview Frame As...",
                initialfile=default_filename,
                defaultextension=".png",
                filetypes=[("PNG Image", "*.png"), ("JPEG Image", "*.jpg"), ("All Files", "*.*")],
            )

            if filepath:
                sbs_image.save(filepath)
                logger.info(f"SBS preview frame saved to: {filepath}")
        except Exception as e:
            logger.error(f"Failed to save SBS preview frame: {e}", exc_info=True)
            messagebox.showerror("Save Error", f"An error occurred while creating or saving the SBS image:\n{e}")
